create or replace function public.finance_dashboard_summary(p_year integer,p_month integer)returns jsonb language plpgsql stable security invoker set search_path=''as $$declare start_date date:=make_date(p_year,p_month,1);end_date date:=(start_date+interval'1 month')::date;result jsonb;begin if not public.has_permission('finance.read')then raise exception'insufficient_permission'using errcode='42501';end if;select jsonb_build_object('accrual_revenue',coalesce((select sum(net_amount)from public.service_periods where year=p_year and month=p_month),0),'cash_collections',coalesce((select sum(amount)from public.payments where payment_date>=start_date and payment_date<end_date),0),'outstanding_receivables',coalesce((select sum(r.total_amount-coalesce(p.paid,0))from public.receivables r left join lateral(select sum(amount)paid from public.payments where receivable_id=r.id)p on true where r.status<>'paid'),0),'overdue_receivables',coalesce((select sum(r.total_amount-coalesce(p.paid,0))from public.receivables r left join lateral(select sum(amount)paid from public.payments where receivable_id=r.id)p on true where r.status<>'paid'and r.due_date<current_date),0),'vendor_costs',coalesce((select sum(amount)from public.vendor_accruals where year=p_year and month=p_month and status<>'cancelled'),0),'payroll_costs',coalesce((select sum(net_payable)from public.payroll_periods where year=p_year and month=p_month and status<>'cancelled'),0),'cash_expenses',abs(coalesce((select sum(amount)from public.finance_transactions where transaction_type='expense'and transaction_date>=start_date and transaction_date<end_date),0)),'estimated_profit',coalesce((select sum(net_amount)from public.service_periods where year=p_year and month=p_month),0)-coalesce((select sum(amount)from public.vendor_accruals where year=p_year and month=p_month and status<>'cancelled'),0)-coalesce((select sum(net_payable)from public.payroll_periods where year=p_year and month=p_month and status<>'cancelled'),0))into result;return result;end$$;
create or replace function public.collection_dashboard_summary()returns jsonb language plpgsql stable security invoker set search_path=''as $$declare result jsonb;begin if not(public.has_permission('collections.read')or public.has_permission('finance.read'))then raise exception'insufficient_permission'using errcode='42501';end if;select jsonb_build_object('outstanding_count',count(*)filter(where r.status<>'paid'),'partial_count',count(*)filter(where r.status='partial'),'overdue_count',count(*)filter(where r.status<>'paid'and r.due_date<current_date),'outstanding_amount',coalesce(sum(r.total_amount-coalesce(p.paid,0))filter(where r.status<>'paid'),0),'overdue_amount',coalesce(sum(r.total_amount-coalesce(p.paid,0))filter(where r.status<>'paid'and r.due_date<current_date),0))into result from public.receivables r left join lateral(select sum(amount)paid from public.payments where receivable_id=r.id)p on true;return result;end$$;
create or replace function public.monthly_profitability(p_from date,p_to date)returns table(year integer,month integer,revenue numeric,vendor_cost numeric,payroll_cost numeric,gross_profit numeric,estimated_net_profit numeric)language plpgsql stable security invoker set search_path=''as $$begin if not public.has_permission('finance.read')then raise exception'insufficient_permission'using errcode='42501';end if;return query with months as(select generate_series(date_trunc('month',p_from)::date,date_trunc('month',p_to)::date,interval'1 month')::date d),rev as(select make_date(sp.year,sp.month,1)d,sum(sp.net_amount)amount from public.service_periods sp group by 1),vc as(select make_date(v.year,v.month,1)d,sum(v.amount)amount from public.vendor_accruals v where v.status<>'cancelled'group by 1),pc as(select make_date(p.year,p.month,1)d,sum(p.net_payable)amount from public.payroll_periods p where p.status<>'cancelled'group by 1)select extract(year from m.d)::integer,extract(month from m.d)::integer,coalesce(r.amount,0),coalesce(v.amount,0),coalesce(p.amount,0),coalesce(r.amount,0)-coalesce(v.amount,0),coalesce(r.amount,0)-coalesce(v.amount,0)-coalesce(p.amount,0)from months m left join rev r using(d)left join vc v using(d)left join pc p using(d)order by m.d;end$$;
create or replace function public.monthly_cashflow(p_from date,p_to date)returns table(year integer,month integer,cash_in numeric,cash_out numeric,net_change numeric)language plpgsql stable security invoker set search_path=''as $$begin if not public.has_permission('accounts.read')then raise exception'insufficient_permission'using errcode='42501';end if;return query with months as(select generate_series(date_trunc('month',p_from)::date,date_trunc('month',p_to)::date,interval'1 month')::date d),tx as(select date_trunc('month',transaction_date)::date d,sum(amount)filter(where transaction_type='income')cash_in,abs(sum(amount)filter(where transaction_type='expense'))cash_out,sum(amount)filter(where transaction_type<>'transfer')net_change from public.finance_transactions group by 1)select extract(year from m.d)::integer,extract(month from m.d)::integer,coalesce(t.cash_in,0),coalesce(t.cash_out,0),coalesce(t.net_change,0)from months m left join tx t using(d)order by m.d;end$$;
create or replace function public.project_profitability(p_year integer,p_month integer)returns table(project_id uuid,client_name text,project_name text,revenue numeric,vendor_cost numeric,gross_profit numeric,margin_percent numeric)language plpgsql stable security invoker set search_path=''as $$begin if not public.has_permission('finance.read')then raise exception'insufficient_permission'using errcode='42501';end if;return query select p.id,c.company_name,p.name,coalesce(sum(sp.net_amount),0),coalesce(sum(sp.cost_amount),0),coalesce(sum(sp.net_amount-sp.cost_amount),0),case when sum(sp.net_amount)>0 then round(sum(sp.net_amount-sp.cost_amount)/sum(sp.net_amount)*100,2)else 0 end from public.projects p join public.clients c on c.id=p.client_id left join public.service_periods sp on sp.project_id=p.id and sp.year=p_year and sp.month=p_month group by p.id,c.company_name,p.name having count(sp.id)>0 order by 6 desc;end$$;
grant execute on function public.finance_dashboard_summary(integer,integer)to authenticated;grant execute on function public.collection_dashboard_summary()to authenticated;grant execute on function public.monthly_profitability(date,date)to authenticated;grant execute on function public.monthly_cashflow(date,date)to authenticated;grant execute on function public.project_profitability(integer,integer)to authenticated;
